"""API routes module for A2A Scanner.

This module defines the HTTP API endpoints for the A2A Scanner, including
routes for scanning agent cards, health checks, and result retrieval.
"""

import json
import tempfile
from pathlib import Path
from typing import Any

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel, Field

from a2ascanner.config.config import Config
from a2ascanner.core.analyzer_factory import build_analyzers, build_core_analyzers
from a2ascanner.core.scan_policy import ScanPolicy
from a2ascanner.core.scanner import Scanner
from a2ascanner.exceptions import (
    A2AScannerError,
    AuthenticationError,
    NetworkError,
    SSRFError,
    TimeoutError,
    ValidationError,
)
from a2ascanner.utils.http_client import fetch_agent_card
from a2ascanner.utils.logging_config import get_logger, set_correlation_id

logger = get_logger(__name__)


router = APIRouter()

_SCANNABLE_EXTENSIONS = frozenset({
    ".py", ".json", ".yaml", ".yml", ".js", ".jsx",
    ".ts", ".tsx", ".mjs", ".html", ".htm", ".xml",
})

# API-only fields stripped when the request body is a raw agent card JSON object
_SCAN_REQUEST_META_FIELDS = frozenset({"analyzers", "policy"})


def _iter_scannable_files(directory: Path):
    """Yield files under *directory* whose extension is in ``_SCANNABLE_EXTENSIONS``."""
    for file_path in directory.rglob("*"):
        if file_path.is_file() and file_path.suffix.lower() in _SCANNABLE_EXTENSIONS:
            yield file_path


def _resolve_policy(policy_name: str | None) -> ScanPolicy:
    """Resolve a policy preset name to a *ScanPolicy*.

    Only built-in presets (``strict``, ``balanced``, ``permissive``) are
    accepted.  Arbitrary file paths are **not** supported via the API to
    prevent path-injection attacks.  Use the CLI for file-based policies.
    """
    if not policy_name:
        return ScanPolicy.default()

    name = policy_name.strip() if isinstance(policy_name, str) else ""
    if not name:
        return ScanPolicy.default()

    try:
        return ScanPolicy.from_preset(name)
    except ValueError:
        logger.warning("Unknown policy preset %r; falling back to default", name)
        return ScanPolicy.default()


# Request models
class AgentCardScanRequest(BaseModel):
    """Request model for agent card scan."""

    agent_card_url: str | None = Field(None, description="URL to agent card")
    agent_card_json: str | None = Field(None, description="Agent card JSON string")
    agent_card_data: dict[str, Any] | None = Field(
        None, description="Agent card as dict"
    )
    analyzers: list[str] | None = Field(
        None,
        description="Analyzers to use; omit for all applicable analyzers (except endpoint)",
    )
    policy: str | None = Field(
        None,
        description="Policy preset: strict, balanced, permissive; omit for default",
    )

    # Allow the root to be the agent card itself
    class Config:
        extra = "allow"


class SourceCodeScanRequest(BaseModel):
    """Request model for source code scan."""

    directory: str = Field(..., description="Path to source code directory")
    analyzers: list[str] | None = Field(
        None,
        description="Analyzers to use; omit for default selection per file type",
    )
    policy: str | None = Field(
        None,
        description="Policy preset: strict, balanced, permissive; omit for default",
    )


class EndpointScanRequest(BaseModel):
    """Request model for endpoint scan."""

    endpoint_url: str = Field(..., description="Endpoint URL to scan")
    policy: str | None = Field(
        None,
        description="Policy preset: strict, balanced, permissive; omit for default",
    )


class FullScanRequest(BaseModel):
    """Request model for full scan."""

    directory: str = Field(..., description="Path to source code directory")
    agent_card_url: str | None = Field(None, description="URL to agent card")
    endpoint_url: str | None = Field(None, description="Endpoint URL to test")
    analyzers: list[str] | None = Field(
        None,
        description="Analyzers to use; omit for default selection per file type",
    )
    policy: str | None = Field(
        None,
        description="Policy preset: strict, balanced, permissive; omit for default",
    )


class FileContentScanRequest(BaseModel):
    """Request model for scanning raw text content as a file."""

    content: str = Field(..., description="Raw text content to scan")
    analyzers: list[str] | None = Field(
        None,
        description="Analyzers to use; omit for default selection per content type",
    )
    policy: str | None = Field(
        None,
        description="Policy preset: strict, balanced, permissive; omit for default",
    )


# Response models
class ScanResponse(BaseModel):
    """Response model for scan operations."""

    success: bool
    message: str
    result: dict[str, Any] | None = None


# Routes
@router.post("/scan/agent-card", response_model=ScanResponse)
async def scan_agent_card(request: AgentCardScanRequest):
    """Scan an A2A agent card.

    Performs shallow security scan of an agent card using specified analyzers.
    """
    # Set correlation ID for request tracking
    request_id = set_correlation_id()

    try:
        config = Config()
        policy = _resolve_policy(request.policy)
        scanner = Scanner(
            config, policy=policy, analyzers=build_analyzers(policy, config=config)
        )
        analyzers_list = request.analyzers if request.analyzers else None

        # Check if the request itself is the agent card (direct JSON post)
        request_dict = request.model_dump(exclude_unset=True)

        # If none of the special fields are set, treat the whole request as agent card
        if (
            not request.agent_card_url
            and not request.agent_card_json
            and not request.agent_card_data
        ):
            # Remove API-only fields if they exist
            agent_card = {
                k: v
                for k, v in request_dict.items()
                if k not in _SCAN_REQUEST_META_FIELDS
            }
            if agent_card and "name" in agent_card:  # Looks like an agent card
                result = await scanner.scan_agent_card(
                    agent_card, analyzers=analyzers_list
                )
            else:
                raise HTTPException(
                    status_code=400,
                    detail={
                        "error": {
                            "code": "INVALID_REQUEST",
                            "message": "Must provide one of: agent_card_url, agent_card_json, agent_card_data, or a valid agent card JSON",
                            "request_id": request_id,
                        }
                    },
                )
        elif request.agent_card_url:
            # Fetch from URL
            try:
                logger.info(f"Fetching agent card from URL: {request.agent_card_url}")
                agent_card = await fetch_agent_card(
                    url=request.agent_card_url,
                    timeout=30.0,
                    verify_ssl=not config.dev_mode,  # Skip SSL verification in dev mode
                    allow_localhost=config.dev_mode,  # Allow localhost in dev mode
                    allow_private_ips=config.dev_mode,  # Allow private IPs in dev mode
                )
                result = await scanner.scan_agent_card(
                    agent_card, analyzers=analyzers_list
                )
                logger.info("Successfully scanned agent card from URL")
            except SSRFError as e:
                logger.error(f"SSRF protection blocked URL: {e.message}")
                raise HTTPException(
                    status_code=403,
                    detail={
                        "error": {
                            "code": "SSRF_BLOCKED",
                            "message": e.message,
                            "details": e.details,
                            "request_id": request_id,
                        }
                    },
                )
            except AuthenticationError as e:
                logger.error(f"Authentication failed: {e.message}")
                raise HTTPException(
                    status_code=401,
                    detail={
                        "error": {
                            "code": "AUTH_FAILED",
                            "message": e.message,
                            "details": e.details,
                            "request_id": request_id,
                        }
                    },
                )
            except TimeoutError as e:
                logger.error(f"Request timed out: {e.message}")
                raise HTTPException(
                    status_code=504,
                    detail={
                        "error": {
                            "code": "TIMEOUT",
                            "message": e.message,
                            "details": e.details,
                            "request_id": request_id,
                        }
                    },
                )
            except NetworkError as e:
                logger.error(f"Network error: {e.message}")
                raise HTTPException(
                    status_code=502,
                    detail={
                        "error": {
                            "code": "NETWORK_ERROR",
                            "message": e.message,
                            "details": e.details,
                            "request_id": request_id,
                        }
                    },
                )
            except ValidationError as e:
                logger.error(f"Validation error: {e.message}")
                raise HTTPException(
                    status_code=400,
                    detail={
                        "error": {
                            "code": "VALIDATION_ERROR",
                            "message": e.message,
                            "details": e.details,
                            "request_id": request_id,
                        }
                    },
                )
        elif request.agent_card_json:
            agent_card = json.loads(request.agent_card_json)
            result = await scanner.scan_agent_card(
                agent_card, analyzers=analyzers_list
            )
        else:  # agent_card_data
            result = await scanner.scan_agent_card(
                request.agent_card_data, analyzers=analyzers_list
            )

        return ScanResponse(
            success=True, message="Agent card scan completed", result=result.to_dict()
        )

    except json.JSONDecodeError as e:
        logger.error(f"JSON decode error: {str(e)}")
        raise HTTPException(
            status_code=400,
            detail={
                "error": {
                    "code": "INVALID_JSON",
                    "message": f"Invalid JSON: {str(e)}",
                    "request_id": request_id,
                }
            },
        )
    except HTTPException:
        # Re-raise HTTP exceptions as-is
        raise
    except A2AScannerError as e:
        logger.error(f"Scanner error: {e.message}", extra={"details": e.details})
        raise HTTPException(
            status_code=500,
            detail={
                "error": {
                    "code": e.__class__.__name__.upper(),
                    "message": e.message,
                    "details": e.details,
                    "request_id": request_id,
                }
            },
        )
    except Exception as e:
        logger.exception("Unexpected error in scan_agent_card")
        raise HTTPException(
            status_code=500,
            detail={
                "error": {
                    "code": "INTERNAL_ERROR",
                    "message": str(e),
                    "request_id": request_id,
                }
            },
        )


@router.post("/scan/file", response_model=ScanResponse)
async def scan_file_content(request: FileContentScanRequest):
    """Scan raw text content using the same rules as scanning a file on disk."""
    set_correlation_id()
    try:
        config = Config()
        policy = _resolve_policy(request.policy)
        scanner = Scanner(
            config, policy=policy, analyzers=build_analyzers(policy, config=config)
        )
        analyzers_list = request.analyzers if request.analyzers else None

        suffix = ".txt"
        try:
            json.loads(request.content)
            suffix = ".json"
        except json.JSONDecodeError:
            pass

        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            suffix=suffix,
            delete=False,
        ) as tmp:
            tmp.write(request.content)
            tmp_path = tmp.name
        try:
            result = await scanner.scan_file(tmp_path, analyzers=analyzers_list)
        finally:
            Path(tmp_path).unlink(missing_ok=True)

        return ScanResponse(
            success=True,
            message="File content scan completed",
            result=result.to_dict(),
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/scan/source-code", response_model=ScanResponse)
async def scan_source_code(request: SourceCodeScanRequest):
    """Scan A2A agent source code.

    Performs deep security scan of source code using specified analyzers.
    """
    try:
        config = Config()
        policy = _resolve_policy(request.policy)
        scanner = Scanner(
            config, policy=policy, analyzers=build_analyzers(policy, config=config)
        )
        analyzers_list = request.analyzers if request.analyzers else None

        # Scan directory using scan_file on all files
        directory = Path(request.directory)
        if not directory.exists():
            raise HTTPException(
                status_code=404, detail=f"Directory not found: {request.directory}"
            )

        all_findings = []
        for file_path in _iter_scannable_files(directory):
            result = await scanner.scan_file(str(file_path), analyzers=analyzers_list)
            all_findings.extend(result.findings)

        # Create aggregated result
        result_dict = {
            "target_type": "source_code",
            "target_name": str(directory),
            "status": "scanned",
            "analyzers": list(scanner.analyzers.keys()),
            "findings_count": len(all_findings),
            "findings": [f.to_dict() for f in all_findings],
        }

        return ScanResponse(
            success=True, message="Source code scan completed", result=result_dict
        )

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@router.post("/scan/endpoint", response_model=ScanResponse)
async def scan_endpoint(request: EndpointScanRequest):
    """Scan an A2A agent endpoint.

    Performs dynamic security testing of a running agent endpoint.
    """
    # Set correlation ID for request tracking
    request_id = set_correlation_id()

    try:
        config = Config()
        policy = _resolve_policy(request.policy)
        scanner = Scanner(
            config, policy=policy, analyzers=build_analyzers(policy, config=config)
        )

        logger.info(f"Starting endpoint scan: {request.endpoint_url}")

        # Scan the endpoint
        result = await scanner.scan_endpoint(
            endpoint_url=request.endpoint_url,
            timeout=30.0,
            verify_ssl=not config.dev_mode,  # Skip SSL verification in dev mode
        )

        logger.info(f"Endpoint scan completed: {request.endpoint_url}")

        return ScanResponse(
            success=True, message="Endpoint scan completed", result=result.to_dict()
        )

    except SSRFError as e:
        logger.error(f"SSRF protection blocked endpoint: {e.message}")
        raise HTTPException(
            status_code=403,
            detail={
                "error": {
                    "code": "SSRF_BLOCKED",
                    "message": e.message,
                    "details": e.details,
                    "request_id": request_id,
                }
            },
        )
    except TimeoutError as e:
        logger.error(f"Endpoint scan timed out: {e.message}")
        raise HTTPException(
            status_code=504,
            detail={
                "error": {
                    "code": "TIMEOUT",
                    "message": e.message,
                    "details": e.details,
                    "request_id": request_id,
                }
            },
        )
    except NetworkError as e:
        logger.error(f"Network error during endpoint scan: {e.message}")
        raise HTTPException(
            status_code=502,
            detail={
                "error": {
                    "code": "NETWORK_ERROR",
                    "message": e.message,
                    "details": e.details,
                    "request_id": request_id,
                }
            },
        )
    except ValidationError as e:
        logger.error(f"Validation error: {e.message}")
        raise HTTPException(
            status_code=400,
            detail={
                "error": {
                    "code": "VALIDATION_ERROR",
                    "message": e.message,
                    "details": e.details,
                    "request_id": request_id,
                }
            },
        )
    except HTTPException:
        # Re-raise HTTP exceptions as-is
        raise
    except A2AScannerError as e:
        logger.error(f"Scanner error: {e.message}", extra={"details": e.details})
        raise HTTPException(
            status_code=500,
            detail={
                "error": {
                    "code": e.__class__.__name__.upper(),
                    "message": e.message,
                    "details": e.details,
                    "request_id": request_id,
                }
            },
        )
    except Exception as e:
        logger.exception("Unexpected error in scan_endpoint")
        raise HTTPException(
            status_code=500,
            detail={
                "error": {
                    "code": "INTERNAL_ERROR",
                    "message": str(e),
                    "request_id": request_id,
                }
            },
        )


@router.post("/scan/full", response_model=ScanResponse)
async def full_scan(request: FullScanRequest):
    """Perform comprehensive scan of an A2A agent.

    Scans agent card (if provided), source code, and endpoint (if provided).
    """
    try:
        config = Config()
        policy = _resolve_policy(request.policy)
        scanner = Scanner(
            config, policy=policy, analyzers=build_analyzers(policy, config=config)
        )
        analyzers_list = request.analyzers if request.analyzers else None
        results = {}

        # Scan agent card if provided
        if request.agent_card_url:
            # URL fetching not implemented
            results["agent_card"] = {"error": "URL fetching not yet implemented"}

        # Scan source code
        directory = Path(request.directory)
        if directory.exists():
            all_findings = []
            for file_path in _iter_scannable_files(directory):
                result = await scanner.scan_file(
                    str(file_path), analyzers=analyzers_list
                )
                all_findings.extend(result.findings)

            results["source_code"] = {
                "target_type": "source_code",
                "target_name": str(directory),
                "status": "scanned",
                "findings_count": len(all_findings),
                "findings": [f.to_dict() for f in all_findings],
            }
        else:
            results["source_code"] = {
                "error": f"Directory not found: {request.directory}"
            }

        # Endpoint scanning not implemented
        if request.endpoint_url:
            results["endpoint"] = {"error": "Endpoint scanning not yet implemented"}

        return ScanResponse(success=True, message="Full scan completed", result=results)

    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


